import {parseTime,formatTime,rallyResults,standings,validateData} from './rules.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='rally-club-v1';let data={version:1,championships:[]},view='overview',rallyId=null,toastTimer;
let loadError=false;try{const saved=localStorage.getItem(KEY);if(saved)data=validateData(JSON.parse(saved));}catch{loadError=true;}
let activeId=data.championships[0]?.id;
const current=()=>data.championships.find(c=>c.id===activeId);
const uid=()=>crypto.randomUUID();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{toast('No se ha podido guardar. Exporta una copia para no perder los cambios.');return false;}}
function confirmAction(title,message,action){$('#confirm-title').textContent=title;$('#confirm-text').textContent=message;$('#confirm-dialog').showModal();$('#confirm-yes').onclick=()=>{$('#confirm-dialog').close();action();};}
$('#confirm-no').onclick=()=>$('#confirm-dialog').close();
const initials=name=>esc(name.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase());
const driverCell=d=>`<div class="driver"><span class="driver-avatar">${initials(d.name)}</span><span>${esc(d.name)}</span></div>`;
const stageCount=c=>c.rallies.reduce((sum,r)=>sum+r.stages,0);
const status=r=>r.closed?'<span class="badge closed">Finalizado</span>':Object.values(r.times).some(a=>a.some(t=>t!==null))?'<span class="badge live">En marcha</span>':'<span class="badge">Pendiente</span>';
const track=`<svg class="track" viewBox="0 0 450 300" aria-hidden="true"><path d="M370 -40C120 10 420 135 270 155S90 70 100 165 300 180 250 270 400 300 420 360"/><path class="center" d="M370 -40C120 10 420 135 270 155S90 70 100 165 300 180 250 270 400 300 420 360"/><circle cx="266" cy="155" r="8" fill="#c7f267"/><circle cx="266" cy="155" r="19" fill="none" stroke="#c7f267" opacity=".4"/></svg>`;
function heading(title,subtitle,c){return `<div class="page-heading"><div><div class="eyebrow">TU GRUPO. TUS REGLAS. TU CAMPEONATO.</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="champ-actions">${c?`<select class="champ-select" id="champ-select" aria-label="Campeonato activo">${data.championships.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}<button class="primary" data-action="create">+ Nuevo campeonato</button></div></div>`;}
function standingsTable(c,compact=false){const rows=standings(c);return `<div class="table-wrap"><table><thead><tr><th>POS.</th><th>PILOTO</th>${compact?'':'<th>VICTORIAS</th><th>PODIOS</th>'}<th>PTS.</th></tr></thead><tbody>${rows.map(d=>`<tr class="${d.rank===1?'first':''}"><td class="pos">${String(d.rank).padStart(2,'0')}</td><td>${driverCell(d)}</td>${compact?'':`<td>${d.wins}</td><td>${d.podiums}</td>`}<td class="points">${d.points}</td></tr>`).join('')}</tbody></table></div>`;}
function rallyRow(r,i){return `<div class="rally-row"><span class="rally-number">${String(i+1).padStart(2,'0')}</span><div class="rally-info"><strong>${esc(r.name)}</strong><small>${r.stages} tramos · ${r.closed?'Resultados oficiales':'Cronometraje manual'}</small></div>${status(r)}<button class="arrow-button" data-rally="${esc(r.id)}" aria-label="Abrir ${esc(r.name)}">↗</button></div>`;}
function render(){const c=current();document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#breadcrumb').textContent={overview:'Campeonato',rallies:'Rallys y tiempos',standings:'Clasificación'}[view];$('#export').disabled=!data.championships.length;
 if(!c){$('#app').innerHTML=heading('Aquí empieza tu campeonato.','Menos cuentas. Más rally.',null)+`<section class="hero"><div class="hero-content"><div class="eyebrow">BIENVENIDO A RALLY CLUB</div><h2>Amigos fuera.<br>Rivales en el tramo.</h2><p>Organiza vuestra copa, registra cada crono y deja que los tiempos hablen.</p><button class="primary" data-action="create">Crear mi primer campeonato →</button></div>${track}<span class="hero-no">EST. 2026 / A FONDO</span></section><div class="stats">${[['01','Crea vuestra copa','Elige rallys y tramos'],['02','Reúne a los pilotos','Añade a tus amigos'],['03','Registra los tiempos','Cada milésima cuenta'],['04','Lucha por el título','5, 3 y 1 puntos por rally']].map(x=>`<div class="stat"><div class="stat-top">${x[0]} / CÓMO FUNCIONA</div><h3 class="section-space">${x[1]}</h3><div class="stat-note">${x[2]}</div></div>`).join('')}</div><section class="panel empty"><div class="empty-icon">⚑</div><h2>La parrilla os está esperando</h2><p>Crea vuestro campeonato para empezar con los tiempos en blanco.<br>También puedes explorar uno de ejemplo.</p><div class="welcome-actions"><button class="primary" data-action="create">+ Crear campeonato</button><button class="secondary" data-action="demo">Probar con un ejemplo</button></div></section>`;return;}
 if(view==='overview'){const closed=c.rallies.filter(r=>r.closed).length,next=c.rallies.find(r=>!r.closed),scores=standings(c);$('#app').innerHTML=heading('El campeonato, al día.','Cada tramo cuenta. El título se decide en el crono.',c)+`<section class="hero"><div class="hero-content"><div class="eyebrow">${closed===c.rallies.length?'BANDERA A CUADROS':'TEMPORADA EN JUEGO'} <span> / </span> ${c.drivers.length} PILOTOS</div><h2>${esc(c.name)}</h2><p>${next?`Próxima batalla: ${esc(next.name)}. ${next.stages} tramos por delante.`:'Todos los rallys han finalizado. Ya tenéis la clasificación definitiva.'}</p><button class="primary" ${next?`data-rally="${esc(next.id)}"`:'data-action="standings"'}>${next?'Introducir tiempos':'Ver clasificación final'} →</button></div>${track}<span class="hero-no">${String(closed).padStart(2,'0')} / ${String(c.rallies.length).padStart(2,'0')} RALLYS</span></section><div class="stats"><div class="stat"><div class="stat-top">RALLYS COMPLETADOS <span class="stat-icon">⚑</span></div><div class="stat-value">${closed}<small>/ ${c.rallies.length}</small></div><div class="stat-note">${c.rallies.length-closed} por disputar</div></div><div class="stat"><div class="stat-top">PILOTOS INSCRITOS <span class="stat-icon">◎</span></div><div class="stat-value">${c.drivers.length}</div><div class="stat-note">Una misma meta</div></div><div class="stat"><div class="stat-top">TRAMOS TOTALES <span class="stat-icon">⌁</span></div><div class="stat-value">${stageCount(c)}</div><div class="stat-note">Milésima a milésima</div></div><div class="stat"><div class="stat-top">PUNTOS DEL LÍDER <span class="stat-icon">♜</span></div><div class="stat-value">${scores[0].points}<small>pts</small></div><div class="stat-note">${closed?(scores.filter(d=>d.rank===1).length>1?'Liderato compartido':esc(scores[0].name)):'Todo por decidir'}</div></div></div><div class="columns"><section class="panel"><div class="panel-heading"><h2>Calendario de rallys</h2><span class="muted">${c.rallies.length} pruebas</span></div>${c.rallies.slice(0,5).map(rallyRow).join('')}${c.rallies.length>5?'<div class="inline-note"><button class="text-button" data-action="rallies">Ver todos los rallys →</button></div>':''}</section><section class="panel"><div class="panel-heading"><h2>Clasificación general</h2><button class="text-button" data-action="standings">Ver completa ↗</button></div>${standingsTable(c,true)}<div class="inline-note">${closed?'Puntos de los rallys finalizados.':'Sin rallys finalizados: todos partís de cero.'}</div></section></div><div class="notice"><span class="podium">5 / 3 / 1</span><div><strong>Cada rally es una nueva oportunidad.</strong> El menor tiempo total gana. Primero, 5 puntos; segundo, 3; tercero, 1.</div></div>`;}
 else if(view==='standings'){$('#app').innerHTML=heading('La lucha por el título.','Los puntos se suman al finalizar cada rally.',c)+`<section class="panel"><div class="panel-heading"><h2>${esc(c.name)}</h2><span class="badge live">${c.rallies.filter(r=>r.closed).length} / ${c.rallies.length} finalizados</span></div>${standingsTable(c)}</section><section class="panel section-space"><div class="panel-heading"><h2>Puntos por rally</h2></div><div class="table-wrap"><table><thead><tr><th>PILOTO</th>${c.rallies.map(r=>`<th>${esc(r.name)}</th>`).join('')}</tr></thead><tbody>${standings(c).map(d=>`<tr><td>${driverCell(d)}</td>${c.rallies.map(r=>`<td>${r.closed?rallyResults(c,r).find(x=>x.id===d.id).points:'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel section-space"><div class="panel-heading"><h2>Reglamento de la copa</h2></div><div class="rules"><strong>Rally:</strong> gana la menor suma de todos los tramos. Puntos: 5, 3 y 1 para los tres primeros; el resto, 0.<br><strong>Empates en un rally:</strong> decide el último tramo; después, el penúltimo y así sucesivamente. Si todos los tiempos coinciden, se comparte puesto y puntos, saltando la siguiente posición.<br><strong>Campeonato:</strong> los pilotos con los mismos puntos comparten posición.<br><strong>Resultados:</strong> un rally solo puede finalizar cuando todos los pilotos tengan todos sus tiempos. Puedes reabrirlo para corregirlos; se retirarán sus puntos hasta volver a finalizarlo.</div></section><button class="quiet delete-button section-space" data-action="delete">Eliminar este campeonato</button>`;}
 else{let r=c.rallies.find(r=>r.id===rallyId)||c.rallies.find(r=>!r.closed)||c.rallies[0];rallyId=r.id;const started=Object.values(r.times).some(a=>a.some(t=>t!==null));$('#app').innerHTML=heading('Contra el crono.','Introduce cada tiempo. Nosotros hacemos las cuentas.',c)+`<div class="toolbar"><select id="rally-select" aria-label="Rally activo">${c.rallies.map((x,i)=>`<option value="${esc(x.id)}" ${x.id===r.id?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(x.name)}${x.closed?' · Finalizado':''}</option>`).join('')}</select>${status(r)}</div><section class="panel"><div class="rally-settings"><label>Nombre del rally<input id="rally-name" value="${esc(r.name)}" maxlength="80" ${r.closed?'disabled':''}></label><label>Tramos<input id="rally-stages" type="number" min="1" max="30" value="${r.stages}" ${r.closed||started?'disabled':''}></label><button class="secondary" data-action="settings" ${r.closed?'disabled':''}>Guardar</button></div><div class="table-wrap"><table class="timing"><thead><tr><th>PILOTO</th>${Array.from({length:r.stages},(_,i)=>`<th>TC ${String(i+1).padStart(2,'0')}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>${c.drivers.map(d=>{const row=rallyResults(c,r).find(x=>x.id===d.id);return `<tr><td>${driverCell(d)}</td>${Array.from({length:r.stages},(_,i)=>`<td><input type="text" inputmode="decimal" autocomplete="off" spellcheck="false" placeholder="0:00.000" aria-label="Tiempo de ${esc(d.name)}, tramo ${i+1}" data-driver="${esc(d.id)}" data-stage="${i}" value="${r.times[d.id]?.[i]!=null?formatTime(r.times[d.id][i]):''}" ${r.closed?'disabled':''}></td>`).join('')}<td class="total" data-total="${esc(d.id)}">${formatTime(row.total)}</td></tr>`;}).join('')}</tbody></table></div><div class="timing-footer"><p class="help">Formato: <strong>3:24.567</strong> o <strong>204.567</strong> segundos.<br>Los tiempos válidos se guardan al salir de la casilla. Todos los tramos son obligatorios.</p><button class="primary" data-action="${r.closed?'reopen':'close'}">${r.closed?'Reabrir para corregir':'Finalizar rally y repartir puntos'} →</button></div></section><section class="panel section-space"><div class="panel-heading"><h2>Clasificación del rally</h2><span class="muted">${r.closed?'Oficial':'Provisional · sin puntos todavía'}</span></div><div id="rally-results"></div></section><div class="notice">ⓘ <span>Los pilotos con tramos pendientes no se clasifican. En caso de empate total, desempata el último tramo y después los anteriores.</span></div>`;renderResults();}
}
function renderResults(){const c=current(),r=c.rallies.find(r=>r.id===rallyId);if(!$('#rally-results'))return;const rows=rallyResults(c,r);const best=rows.find(d=>d.total!==null)?.total;$('#rally-results').innerHTML=`<div class="table-wrap"><table><thead><tr><th>POS.</th><th>PILOTO</th><th>TIEMPO</th><th>DIF.</th><th>PTS.</th></tr></thead><tbody>${rows.map(d=>`<tr><td class="pos">${d.rank??'—'}</td><td>${driverCell(d)}</td><td>${d.total!==null?formatTime(d.total):`${d.completed}/${r.stages} tramos`}</td><td>${d.total===null?'—':d.total===best?'Líder':`+${formatTime(d.total-best)}`}</td><td class="points">${r.closed?d.points:'—'}</td></tr>`).join('')}</tbody></table></div>`;rows.forEach(d=>{const el=Array.from(document.querySelectorAll('[data-total]')).find(el=>el.dataset.total===d.id);if(el)el.textContent=formatTime(d.total);});}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;render();return;}const rally=e.target.closest('[data-rally]');if(rally){view='rallies';rallyId=rally.dataset.rally;render();return;}const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;const c=current(),r=c?.rallies.find(x=>x.id===rallyId);if(a==='create'){$('#create-error').textContent='';$('#create-dialog').showModal();}if(a==='demo')makeDemo();if(a==='standings'||a==='rallies'){view=a;render();}if(a==='settings'){const name=$('#rally-name').value.trim(),stages=Number($('#rally-stages').value);if(!name||!Number.isInteger(stages)||stages<1||stages>30)return toast('Introduce un nombre y entre 1 y 30 tramos.');r.name=name;if(!Object.values(r.times).some(a=>a.some(t=>t!==null)))r.stages=stages;save();render();toast('Rally actualizado.');}if(a==='close'){if(document.querySelector('[aria-invalid="true"]'))return toast('Corrige los tiempos marcados antes de finalizar.');if(rallyResults(c,r).some(d=>d.total===null))return toast('Faltan tiempos. Completa todos los tramos de todos los pilotos.');confirmAction('¿Finalizar el rally?','Se fijará la clasificación y se sumarán 5, 3 y 1 puntos. Podrás reabrirlo si necesitas corregir un tiempo.',()=>{r.closed=true;save();render();toast('Rally finalizado. Puntos sumados al campeonato.');});}if(a==='reopen')confirmAction('¿Reabrir el rally?','Sus puntos se retirarán de la general hasta que vuelvas a finalizarlo.',()=>{r.closed=false;save();render();});if(a==='delete')confirmAction('¿Eliminar el campeonato?','Se borrarán sus pilotos, rallys y tiempos de este dispositivo. Exporta una copia antes si quieres conservarlos.',()=>{data.championships=data.championships.filter(x=>x.id!==c.id);activeId=data.championships[0]?.id;rallyId=null;save();render();});});
document.addEventListener('change',e=>{if(e.target.id==='champ-select'){activeId=e.target.value;rallyId=null;render();}if(e.target.id==='rally-select'){rallyId=e.target.value;render();}if(e.target.matches('[data-driver]')){const input=e.target,c=current(),r=c.rallies.find(x=>x.id===rallyId),raw=input.value.trim(),ms=raw?parseTime(raw):null;if(raw&&ms===null){input.setAttribute('aria-invalid','true');input.setCustomValidity('Usa minutos:segundos.milésimas o segundos, con un tiempo mayor que cero.');input.reportValidity();toast('Tiempo no válido. Ejemplo: 3:24.567.');return;}input.removeAttribute('aria-invalid');input.setCustomValidity('');r.times[input.dataset.driver]??=Array(r.stages).fill(null);r.times[input.dataset.driver][Number(input.dataset.stage)]=ms;input.value=ms===null?'':formatTime(ms);save();renderResults();$('#rally-stages').disabled=Object.values(r.times).some(a=>a.some(t=>t!==null));}});
$('#cancel-create').onclick=()=>$('#create-dialog').close();
$('#create-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),names=f.get('drivers').split('\n').map(n=>n.trim()).filter(Boolean),count=Number(f.get('rallies')),stages=Number(f.get('stages'));if(!name||names.length<2||names.length>30||names.some(n=>n.length>40)||new Set(names.map(n=>n.toLowerCase())).size!==names.length){$('#create-error').textContent='Añade de 2 a 30 pilotos con nombres únicos de hasta 40 caracteres.';return;}if(!Number.isInteger(count)||count<1||count>30||!Number.isInteger(stages)||stages<1||stages>30)return;if(data.championships.length>=100){$('#create-error').textContent='Límite de 100 campeonatos. Exporta y elimina alguno.';return;}const c={id:uid(),name,drivers:names.map(name=>({id:uid(),name})),rallies:Array.from({length:count},(_,i)=>({id:uid(),name:`Rally ${i+1}`,stages,times:{},closed:false}))};data.championships.push(c);activeId=c.id;rallyId=null;view='overview';save();$('#create-dialog').close();e.target.reset();render();toast('Campeonato creado. ¡A la línea de salida!');};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rally-club-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia exportada con todos los campeonatos.');};
$('#import').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('El archivo es demasiado grande (máximo 5 MB).');const imported=validateData(JSON.parse(await file.text()));if(!imported.championships.length)throw Error('La copia no contiene campeonatos.');if(data.championships.length+imported.championships.length>100)throw Error('La importación supera el límite de 100 campeonatos.');confirmAction('¿Importar la copia?',`Se añadirán ${imported.championships.length} campeonatos. Los actuales se conservarán; los importados serán copias independientes.`,()=>{for(const c of imported.championships){c.id=uid();data.championships.push(c);}activeId=imported.championships[0].id;rallyId=null;view='overview';save();render();toast('Copia importada.');});}catch(error){toast(error instanceof SyntaxError?'No se puede leer el archivo JSON.':error.message);}};
function makeDemo(){const c={id:uid(),name:'Copa de los viernes · Ejemplo',drivers:['Enrique','Álex','Marta','Dani'].map(name=>({id:uid(),name})),rallies:['Rally Montecarlo','Rally de Portugal','Rally de Finlandia','Rally de Cataluña'].map(name=>({id:uid(),name,stages:3,closed:false,times:{}}))};c.rallies[0].closed=true;c.drivers.forEach((d,i)=>{c.rallies[0].times[d.id]=[185240+i*1720,212530+i*2300,174820+i*1400];c.rallies[1].times[d.id]=[202180+i*1370,null,null];});data.championships.push(c);activeId=c.id;view='overview';save();render();toast('Campeonato de ejemplo. Puedes crear el vuestro cuando quieras.');}
render();if(loadError)toast('No se ha podido leer el guardado. Importa una copia; los datos anteriores no se han sobrescrito.');
